import { Component, inject } from '@angular/core';
import { MatBottomSheet, MatBottomSheetModule, MatBottomSheetRef } from '@angular/material/bottom-sheet';
import { MatButtonModule } from '@angular/material/button';
import { MatListModule } from '@angular/material/list';

@Component({
  selector: 'app-actions-sheet',
  standalone: true,
  imports: [MatListModule],
  template: `
    <mat-nav-list>
      <a mat-list-item (click)="close()">Share</a>
      <a mat-list-item (click)="close()">Delete</a>
    </mat-nav-list>
  `,
})
export class ActionsSheetComponent {
  private ref = inject(MatBottomSheetRef<ActionsSheetComponent>);

  close(): void {
    this.ref.dismiss();
  }
}

@Component({
  selector: 'app-example',
  standalone: true,
  imports: [MatButtonModule, MatBottomSheetModule],
  template: `<button mat-button (click)="openSheet()">Open</button>`,
})
export class ExampleComponent {
  private bottomSheet = inject(MatBottomSheet);

  openSheet(): void {
    this.bottomSheet.open(ActionsSheetComponent);
  }
}
